=== file: main.loom ===
budget { tokens: 300000  calls: 100 }

agent TermAnalyst {
    model: "gpt-6-luna"
    prompt: "term-analyst"
    temperature: 0.1
    guard { pii: mask }
}

agent BeginnerRewriter {
    model: "gpt-6-luna"
    prompt: "beginner-rewriter"
    temperature: 0.3
    guard { pii: mask }
}

agent TermVerifier {
    model: "gpt-6-luna"
    prompt: "term-verifier"
    temperature: 0.1
    guard { pii: mask }
}

workflow Main(submitted_document_payload) {
    delegate "Identify technical terms in this document. Return the terms, their proposed explanations, whether any are uncertain, and whether human review is needed.\n\nDocument:\n{submitted_document_payload}" to TermAnalyst -> segmentation_report expecting {
        needs_human: enum["YES", "NO"],
        terms: list<string>,
        explanations: list<string>,
        uncertain_terms: list<string>
    } retry 1 backoff 2s timeout 90s on_failure {
        halt "Term analysis failed; no rewrite was released: {_error}"
    }

    set reviewer_guidance = "No human-supplied term guidance."

    alt (segmentation_report.needs_human == "YES") {
        human_prompt "A technical term needs review. Provide verified explanations for the uncertain terms, or mark each one unresolved:\n{segmentation_report.uncertain_terms}" -> reviewer_guidance
    }

    delegate "Rewrite this document for beginners. Preserve its meaning, explain supported technical terms on first use, process every section in order, and do not omit content. For documents longer than 20,000 words, divide the work into sections and rewrite every section. Use the supplied term analysis and human guidance. Keep any unresolved term explicitly flagged; do not guess.\n\nDocument:\n{submitted_document_payload}\n\nTerm analysis:\n{segmentation_report}\n\nHuman guidance:\n{reviewer_guidance}" to BeginnerRewriter -> rewritten_document expecting {
        rewritten_text: string,
        unresolved_terms: list<string>
    } retry 1 backoff 2s timeout 90s on_failure {
        halt "Rewrite failed; no unchecked document was released: {_error}"
    }

    delegate "Independently check the entire rewritten document against the source and identified terms. Check that every technical term is explained, explanations are supported, and unresolved terms are explicitly flagged. Do not supply speculative definitions.\n\nSource document:\n{submitted_document_payload}\n\nTerm analysis:\n{segmentation_report}\n\nRewrite:\n{rewritten_document.rewritten_text}\n\nUnresolved terms already flagged:\n{rewritten_document.unresolved_terms}" to TermVerifier -> verification_report expecting {
        status: enum["OK", "REVIEW"],
        unexplained_terms: list<string>,
        unsupported_terms: list<string>
    } retry 1 backoff 2s timeout 90s on_failure {
        halt "Independent verification failed; no unchecked document was released: {_error}"
    }

    set final_verification = verification_report
    set final_rewrite = rewritten_document
    set followup_guidance = "No follow-up human guidance."

    alt (verification_report.status == "REVIEW") {
        human_prompt "Verification found terms that need review. Provide verified explanations or mark each term unresolved. Unresolved terms must remain explicitly flagged.\n\nUnexplained terms:\n{verification_report.unexplained_terms}\nUnsupported terms:\n{verification_report.unsupported_terms}" -> followup_guidance

        delegate "Revise the document using the human guidance. Preserve meaning, explain only terms supported by the source or verified human guidance, and explicitly flag every unresolved term. Keep the full document and every section.\n\nSource document:\n{submitted_document_payload}\n\nCurrent rewrite:\n{rewritten_document.rewritten_text}\n\nCurrent unresolved terms:\n{rewritten_document.unresolved_terms}\n\nVerification findings:\n{verification_report}\n\nHuman guidance:\n{followup_guidance}" to BeginnerRewriter -> revised_document expecting {
            rewritten_text: string,
            unresolved_terms: list<string>
        } retry 1 backoff 2s timeout 90s on_failure {
            halt "Revision failed; no unchecked document was released: {_error}"
        }

        delegate "Independently verify the revised document against the source. Return REVIEW for any unexplained or unsupported term, and ensure unresolved terms are explicitly flagged. Do not guess.\n\nSource document:\n{submitted_document_payload}\n\nTerm analysis:\n{segmentation_report}\n\nRevised document:\n{revised_document.rewritten_text}\n\nUnresolved terms:\n{revised_document.unresolved_terms}" to TermVerifier -> final_verification expecting {
            status: enum["OK", "REVIEW"],
            unexplained_terms: list<string>,
            unsupported_terms: list<string>
        } retry 1 backoff 2s timeout 90s on_failure {
            halt "Final verification failed; no unchecked document was released: {_error}"
        }

        set final_rewrite = revised_document
    }

    set completion_label = "CHECKED"

    alt (final_verification.status == "REVIEW") {
        set completion_label = "NEEDS_HUMAN_REVIEW"
    }

    return {
        status: completion_label,
        rewritten_document: final_rewrite.rewritten_text,
        unresolved_terms: final_rewrite.unresolved_terms,
        verification: final_verification
    }
}
